extern "C" float sqrtf(float);

struct vector3d {
    float x, y, z;
    vector3d() {}
    vector3d(float X, float Y, float Z) : x(X), y(Y), z(Z) {}
    vector3d operator-(const vector3d& v) const { return vector3d(x-v.x, y-v.y, z-v.z); }
    vector3d& operator-=(const vector3d& v) { x-=v.x; y-=v.y; z-=v.z; return *this; }
    void normalize() {
        float len2 = x*x + y*y + z*z;
        if (len2 > 1.0e-10f) {
            float len = sqrtf(len2);
            float inv = 1.0f / len;
            x *= inv; y *= inv; z *= inv;
        }
    }
};
inline float dot(const vector3d& a, const vector3d& b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
inline vector3d operator*(const vector3d& v, float f) { return vector3d(v.x*f, v.y*f, v.z*f); }
inline vector3d cross(const vector3d& a, const vector3d& b) { return vector3d(a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x); }

extern const vector3d YVEC;
__asm__(".equ YVEC, 0x00554458");
enum WaveMarkerEnum { WAVE_MarkerLipMark11 = 23, WAVE_MarkerLipMark13 = 29 };
const vector3d *WAVE_GetMarker(WaveMarkerEnum);
__asm__(".equ WAVE_GetMarker__F14WaveMarkerEnum, 0x0037D7E8");

