struct board_controller {
    void ResetPhysics() __asm__("ResetPhysics__20SurfBoardObjectClass");
};
class kellyslater_controller {
    char padding[0x37c];
    board_controller my_board_controller;
public:
    void Reset();
    void ResetPhysics() { my_board_controller.ResetPhysics(); Reset(); }
};
__asm__(".equ Reset__22kellyslater_controller, 0x00211538");

class SurfBoardObjectClass {
    char padding0[0x9dc];
    kellyslater_controller *ksctrl;
    char padding1[0xd0];
    vector3d lip_vec;
    vector3d lip_normal;
public:
    kellyslater_controller *get_ks_controller() { return ksctrl; }
    void OnNewWave();
};

void SurfBoardObjectClass::OnNewWave()
{
    lip_vec = *WAVE_GetMarker(WAVE_MarkerLipMark13) - *WAVE_GetMarker(WAVE_MarkerLipMark11);
    lip_vec -= YVEC*dot(YVEC, lip_vec);
    lip_vec.normalize();
    int curbeach = g_game_ptr->get_beach_id ();
    if (BeachDataArray[curbeach].bdir)
        lip_normal = cross(YVEC, lip_vec);
    else
        lip_normal = cross(lip_vec, YVEC);

    get_ks_controller()->ResetPhysics();
    //ResetPhysics();	// ??? Do we want this here? (dc 01/24/02)
}
